<?php
 namespace Pterodactyl\Models\Dezerx; use Pterodactyl\Models\User; use Pterodactyl\Models\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo; class DiscordLink extends Model { public const RESOURCE_NAME = 'discord_link'; protected bool $immutableDates = true; protected $table = 'dezerx_discord_links'; protected $guarded = ['id']; protected $casts = [ 'user_id' => 'int', 'joined_guild' => 'bool', ]; public static array $validationRules = [ 'user_id' => 'required|int|exists:users,id', 'discord_id' => 'required|string|max:32', 'username' => 'required|string|max:191', ]; public function owner(): BelongsTo { return $this->belongsTo(User::class, 'user_id'); } public function avatarUrl(): string { if ($this->avatar === null || $this->avatar === '') { return 'https://cdn.discordapp.com/embed/avatars/0.png'; } return sprintf('https://cdn.discordapp.com/avatars/%s/%s.png?size=64', $this->discord_id, $this->avatar); } } 